    image_key: Optional[Union[int, Value]] = Field(default=None, alias='image_key', description='This field allow to distinguish different types of exposure to the same detector "data" field. Some techniques require frequent (re-)calibration inbetween measurements and this way of recording the different measurements preserves the chronological order with is important for correct processing. This is used for example in tomography (:ref:`NXtomo`) sample projections, dark and flat images, a magic number is recorded per frame. The key is as follows: * projection (sample) = 0 * flat field = 1 * dark field = 2 * invalid = 3 * background (no sample, but buffer where applicable) = 4 In cases where the data is of type :ref:`NXlog` this can also be an NXlog.', json_schema_extra={'nx_unit_category': None, 'nx_is_attribute': False})
    countrate_correction_applied: Optional[Union[bool, Value]] = Field(default=None, alias='countrate_correction_applied', description='Counting detectors usually are not able to measure all incoming particles, especially at higher count-rates. Count-rate correction is applied to account for these errors. True when count-rate correction has been applied, false otherwise.', json_schema_extra={'nx_unit_category': None, 'nx_is_attribute': False})
    countrate_correction_lookup_table: Optional[Union[float, Value]] = Field(default=None, alias='countrate_correction_lookup_table', description='The countrate_correction_lookup_table defines the LUT used for count-rate correction. It maps a measured count :math:`c` to its corrected value :math:`countrate/_correction/_lookup/_table[c]`. :math:`m` denotes the length of the table.', json_schema_extra={'nx_unit_category': None, 'nx_is_attribute': False})
    virtual_pixel_interpolation_applied: Optional[Union[bool, Value]] = Field(default=None, alias='virtual_pixel_interpolation_applied', description='True when virtual pixel interpolation has been applied, false otherwise. When virtual pixel interpolation is applied, values of some pixels may contain interpolated values. For example, to account for space between readout chips on a module, physical pixels on edges and corners between chips may have larger sensor areas and counts may be distributed between their logical pixels.', json_schema_extra={'nx_unit_category': None, 'nx_is_attribute': False})
    bit_depth_readout: Optional[Union[int, Value]] = Field(default=None, alias='bit_depth_readout', description="How many bits the electronics reads per pixel. With CCD's and single photon counting detectors, this must not align with traditional integer sizes. This can be 4, 8, 12, 14, 16, ...", json_schema_extra={'nx_unit_category': None, 'nx_is_attribute': False})
    detector_readout_time: Optional[Union[float, Value]] = Field(default=None, alias='detector_readout_time', description='Time it takes to read the detector (typically milliseconds). This is important to know for time resolved experiments. Unit category: NX_TIME.', json_schema_extra={'nx_unit_category': 'NX_TIME', 'nx_is_attribute': False})
    trigger_delay_time: Optional[Union[float, Value]] = Field(default=None, alias='trigger_delay_time', description='Time it takes to start exposure after a trigger signal has been received. This is the reaction time of the detector firmware after receiving the trigger signal to when the detector starts to acquire the exposure, including any user set delay.. This is important to know for time resolved experiments. Unit category: NX_TIME.', json_schema_extra={'nx_unit_category': 'NX_TIME', 'nx_is_attribute': False})
    trigger_delay_time_set: Optional[Union[float, Value]] = Field(default=None, alias='trigger_delay_time_set', description='User-specified trigger delay. Unit category: NX_TIME.', json_schema_extra={'nx_unit_category': 'NX_TIME', 'nx_is_attribute': False})
    trigger_internal_delay_time: Optional[Union[float, Value]] = Field(default=None, alias='trigger_internal_delay_time', description='Time it takes to start exposure after a trigger signal has been received. This is the reaction time of the detector hardware after receiving the trigger signal to when the detector starts to acquire the exposure. It forms the lower boundary of the trigger_delay_time when the user does not request an additional delay. Unit category: NX_TIME.', json_schema_extra={'nx_unit_category': 'NX_TIME', 'nx_is_attribute': False})
    trigger_dead_time: Optional[Union[float, Value]] = Field(default=None, alias='trigger_dead_time', description='Time during which no new trigger signal can be accepted. Typically this is the trigger_delay_time + exposure_time + readout_time. This is important to know for time resolved experiments. Unit category: NX_TIME.', json_schema_extra={'nx_unit_category': 'NX_TIME', 'nx_is_attribute': False})
    frame_time: Optional[Union[float, Value]] = Field(default=None, alias='frame_time', description='This is time for each frame. This is exposure_time + readout time. Unit category: NX_TIME.', json_schema_extra={'nx_unit_category': 'NX_TIME', 'nx_is_attribute': False})
    gain_setting: Optional[Union[str, Value]] = Field(default=None, alias='gain_setting', description='The gain setting of the detector. This is a detector-specific value meant to document the gain setting of the detector during data collection, for detectors with multiple available gain settings. Examples of gain settings include: * ``standard`` * ``fast`` * ``auto`` * ``high`` * ``medium`` * ``low`` * ``mixed high to medium`` * ``mixed medium to low`` Developers are encouraged to use one of these terms, or to submit additional terms to add to the list.', json_schema_extra={'nx_unit_category': None, 'nx_is_attribute': False})
    saturation_value: Optional[Union[float, Value]] = Field(default=None, alias='saturation_value', description='The value at which the detector goes into saturation. Especially common to CCD detectors, the data is known to be invalid above this value. For example, given a saturation_value and an underload_value, the valid pixels are those less than or equal to the saturation_value and greater than or equal to the underload_value. The precise type should match the type of the data.', json_schema_extra={'nx_unit_category': None, 'nx_is_attribute': False})
    underload_value: Optional[Union[float, Value]] = Field(default=None, alias='underload_value', description='The lowest value at which pixels for this detector would be reasonably measured. The data is known to be invalid below this value. For example, given a saturation_value and an underload_value, the valid pixels are those less than or equal to the saturation_value and greater than or equal to the underload_value. The precise type should match the type of the data.', json_schema_extra={'nx_unit_category': None, 'nx_is_attribute': False})
    number_of_cycles: Optional[Union[int, Value]] = Field(default=None, alias='number_of_cycles', description='CCD images are sometimes constructed by summing together multiple short exposures in the electronics. This reduces background etc. This is the number of short exposures used to sum images for an image.', json_schema_extra={'nx_unit_category': None, 'nx_is_attribute': False})
    sensor_material: Optional[Union[str, Value]] = Field(default=None, alias='sensor_material', description='At times, radiation is not directly sensed by the detector. Rather, the detector might sense the output from some converter like a scintillator. This is the name of this converter material.', json_schema_extra={'nx_unit_category': None, 'nx_is_attribute': False})
    sensor_thickness: Optional[Union[float, Value]] = Field(default=None, alias='sensor_thickness', description='At times, radiation is not directly sensed by the detector. Rather, the detector might sense the output from some converter like a scintillator. This is the thickness of this converter material. Unit category: NX_LENGTH.', json_schema_extra={'nx_unit_category': 'NX_LENGTH', 'nx_is_attribute': False})
    threshold_energy: Optional[Union[float, Value]] = Field(default=None, alias='threshold_energy', description='Single photon counter detectors can be adjusted for a certain energy range in which they work optimally. This is the energy setting for this. Unit category: NX_ENERGY.', json_schema_extra={'nx_unit_category': 'NX_ENERGY', 'nx_is_attribute': False})
    detector_module: Dict[str, NXDetectorModule] = Field(default_factory=dict, alias='DETECTOR_MODULE', description='For use in special cases where the data in NXdetector is represented in several parts, each with a separate geometry.', json_schema_extra={'nx_unit_category': None, 'nx_is_attribute': False})
    depends_on: Optional[Union[str, Value]] = Field(default=None, alias='depends_on', description='The reference point of the detector is the center of the first pixel. In complex geometries the NXoff_geometry groups can be used to provide an unambiguous reference.', json_schema_extra={'nx_unit_category': None, 'nx_is_attribute': False})
